import sys
PARAMS = {'cpu': ['jab', 'block', 'kick', 'jab', 'hook', 'block']}
AUTO = ['hook', 'kick', 'jab', 'special', 'block', 'hook', 'kick', 'jab', 'hook', 'block', 'kick', 'special']

MOVES = {"jab": 6, "hook": 10, "kick": 14, "special": 20, "block": 0}

def bout(moves):
    php, chp = 100, 100
    cpu_pattern = PARAMS["cpu"]
    special_cd = 0
    log = []
    for rnd, mv in enumerate(moves):
        if mv not in MOVES:
            log.append("Round %d: unknown move %s, skipped" % (rnd + 1, mv))
            continue
        cpu = cpu_pattern[rnd % len(cpu_pattern)]
        dmg_to_cpu, dmg_to_player = 0, 0
        if mv == "special" and special_cd > 0:
            log.append("Round %d: special on cooldown, jab instead" % (rnd + 1))
            mv = "jab"
        if mv == "special":
            special_cd = 4
        if special_cd > 0:
            special_cd -= 1
        if mv != "block":
            dmg_to_cpu = MOVES[mv]
            if cpu == "block":
                dmg_to_cpu = dmg_to_cpu * 3 // 10
        if cpu != "block":
            dmg_to_player = MOVES[cpu]
            if mv == "block":
                dmg_to_player = dmg_to_player * 3 // 10
        chp = max(0, chp - dmg_to_cpu)
        php = max(0, php - dmg_to_player)
        log.append("Round %d: you %s vs cpu %s -> you HP %d cpu HP %d" % (rnd + 1, mv, cpu, php, chp))
        if php <= 0 or chp <= 0:
            break
    return php, chp, log

def auto_play():
    print("Fighting tribute: auto session")
    php, chp, log = bout(AUTO)
    for line in log:
        print(line)
    score = max(0, php - chp) + (100 if chp <= 0 else 0)
    print("FINAL SCORE: %d" % score)
    print("RESULT: %s" % ("WIN" if chp <= 0 else "LOSE" if php <= 0 else "DRAW"))

def play():
    print("Fighting tribute: type jab/hook/kick/special/block each round, or quit.")
    moves = []
    for line in sys.stdin:
        mv = line.strip().lower()
        if mv == "quit":
            break
        if mv not in MOVES:
            print("Unknown move: %s" % mv)
            continue
        moves.append(mv)
        php, chp, log = bout(moves)
        print(log[-1])
        if php <= 0 or chp <= 0:
            break
    php, chp, log = bout(moves)
    score = max(0, php - chp) + (100 if chp <= 0 else 0)
    print("FINAL SCORE: %d" % score)
    print("RESULT: %s" % ("WIN" if chp <= 0 else "LOSE" if php <= 0 else "QUIT" if not moves else "DRAW"))

if __name__ == "__main__":
    if "--play" in sys.argv:
        play()
    else:
        auto_play()

import sys
PARAMS = {'distance': 100, 'obstacles': [[35, 2], [65, 0]], 'rivals': [12, 16, 20]}
AUTO = ['accel', 'accel', 'accel', 'accel', 'accel', 'accel', 'accel', 'accel', 'accel', 'accel']

def race(cmds):
    dist, speed, lane, time, penalties = 0, 0, 1, 0, 0
    obstacles = dict((d, l) for d, l in PARAMS["obstacles"])
    log = []
    for tick, cmd in enumerate(cmds):
        if cmd == "accel":
            speed = min(200, speed + 20)
        elif cmd == "brake":
            speed = max(0, speed - 40)
        elif cmd == "left":
            lane = max(0, lane - 1)
        elif cmd == "right":
            lane = min(2, lane + 1)
        dist += speed // 10
        time += 1
        crashed = False
        for d, l in obstacles.items():
            if dist >= d and dist - speed // 10 < d and l == lane and speed > 60:
                speed = 0
                penalties += 5
                crashed = True
        log.append("Tick %d: %s dist %d speed %d lane %d %s" % (tick + 1, cmd, dist, speed, lane, "CRASH" if crashed else "ok"))
        if dist >= PARAMS["distance"]:
            break
    return dist, time + penalties, log

def auto_play():
    print("Racing tribute: auto session")
    dist, total, log = race(AUTO)
    for line in log:
        print(line)
    rivals = PARAMS["rivals"]
    place = 1 + sum(1 for r in rivals if r < total)
    print("FINAL SCORE: %d" % max(0, 1000 - total * 10 + (4 - place) * 50))
    print("RESULT: FINISHED place %d time %d" % (place, total))

def play():
    print("Racing tribute: type accel/brake/left/right each tick, or quit. Finish %d m first." % PARAMS["distance"])
    cmds = []
    for line in sys.stdin:
        cmd = line.strip().lower()
        if cmd == "quit":
            break
        if cmd not in ("accel", "brake", "left", "right"):
            print("Unknown command: %s" % cmd)
            continue
        cmds.append(cmd)
        dist, total, log = race(cmds)
        print(log[-1])
        if dist >= PARAMS["distance"]:
            break
    dist, total, log = race(cmds)
    rivals = PARAMS["rivals"]
    place = 1 + sum(1 for r in rivals if r < total)
    print("FINAL SCORE: %d" % max(0, 1000 - total * 10 + (4 - place) * 50))
    print("RESULT: %s" % ("FINISHED place %d time %d" % (place, total) if dist >= PARAMS["distance"] else "QUIT"))

if __name__ == "__main__":
    if "--play" in sys.argv:
        play()
    else:
        auto_play()

import sys
PARAMS = {'pieces': ['ruby', 'sapphire', 'topaz', 'emerald', 'ruby', 'sapphire', 'topaz', 'emerald']}
AUTO = [['drop'], ['left', 'drop'], ['right', 'drop'], ['drop'], ['rotate', 'drop'], ['left', 'left', 'drop'], ['right', 'rotate', 'drop'], ['drop']]

def auto_play():
    heights = [0] * 6
    score, lines = 0, 0
    print("Puzzle tribute: auto session")
    for pi, piece in enumerate(PARAMS["pieces"]):
        cmds = AUTO[pi] if pi < len(AUTO) else ["drop"]
        col, vertical = 2, False
        for cmd in cmds:
            if cmd == "left":
                col = max(0, col - 1)
            elif cmd == "right":
                col = min(5, col + 1)
            elif cmd == "rotate":
                vertical = not vertical
            elif cmd == "drop":
                break
        if vertical:
            heights[col] += 2
        else:
            if col >= 5:
                col = 4
            heights[col] += 1
            heights[col + 1] += 1
        cleared = 0
        while min(heights) > 0:
            heights = [h - 1 for h in heights]
            cleared += 1
        lines += cleared
        score += cleared * 100 + 10
        print("Piece %d: %s col %d %s heights %s score %d" % (pi + 1, piece, col, "vertical" if vertical else "flat", heights, score))
    print("FINAL SCORE: %d" % score)
    print("RESULT: LINES %d" % lines)

def play():
    heights = [0] * 6
    score, lines = 0, 0
    print("Puzzle tribute: type left/right/rotate/drop per piece, or quit. Fill rows to clear them.")
    pi = 0
    col, vertical = 2, False
    for line in sys.stdin:
        cmd = line.strip().lower()
        if cmd == "quit":
            break
        if pi >= len(PARAMS["pieces"]):
            break
        if cmd == "left":
            col = max(0, col - 1)
        elif cmd == "right":
            col = min(5, col + 1)
        elif cmd == "rotate":
            vertical = not vertical
        elif cmd == "drop":
            piece = PARAMS["pieces"][pi]
            if vertical:
                heights[col] += 2
            else:
                if col >= 5:
                    col = 4
                heights[col] += 1
                heights[col + 1] += 1
            cleared = 0
            while min(heights) > 0:
                heights = [h - 1 for h in heights]
                cleared += 1
            lines += cleared
            score += cleared * 100 + 10
            print("Piece %d: %s heights %s score %d" % (pi + 1, piece, heights, score))
            pi += 1
            col, vertical = 2, False
        else:
            print("Unknown command: %s" % cmd)
    print("FINAL SCORE: %d" % score)
    print("RESULT: LINES %d" % lines)

if __name__ == "__main__":
    if "--play" in sys.argv:
        play()
    else:
        auto_play()

import sys
PARAMS = {'shots': 10}
AUTO = [2, 5, 8, 1, 4, 7, 0, 3, 6, 9]

def hoop_pos(shot):
    return (shot * 3 + 2) % 10

def auto_play():
    baskets = 0
    print("Sports tribute: auto session")
    for i, aim in enumerate(AUTO):
        pos = hoop_pos(i)
        hit = (aim == pos)
        if hit:
            baskets += 1
        print("Shot %d: aim %d hoop was %d %s baskets %d" % (i + 1, aim, pos, "BASKET" if hit else "MISS", baskets))
    print("FINAL SCORE: %d" % (baskets * 2))
    print("RESULT: BASKETS %d/%d" % (baskets, len(AUTO)))

def play():
    baskets, shot = 0, 0
    aim = 5
    print("Sports tribute: type 'aim N' (0-9) then 'shoot' each turn, or quit. The hoop moves in a pattern; learn it.")
    for line in sys.stdin:
        cmd = line.strip().lower()
        if cmd == "quit":
            break
        parts = cmd.split()
        if len(parts) == 2 and parts[0] == "aim":
            try:
                aim = int(parts[1]) % 10
            except ValueError:
                print("Use: aim N")
            continue
        if cmd == "shoot":
            pos = hoop_pos(shot)
            hit = (aim == pos)
            if hit:
                baskets += 1
            print("Shot %d: aim %d hoop was %d %s baskets %d" % (shot + 1, aim, pos, "BASKET" if hit else "MISS", baskets))
            shot += 1
            if shot >= PARAMS["shots"]:
                break
            continue
        print("Use: aim N, then shoot")
    print("FINAL SCORE: %d" % (baskets * 2))
    print("RESULT: BASKETS %d/%d" % (baskets, PARAMS["shots"]))

if __name__ == "__main__":
    if "--play" in sys.argv:
        play()
    else:
        auto_play()

import sys
PARAMS = {'map': ['#######', '#T...P#', '#.###.#', '#E...M#', '#######'], 'monster_hp': 50}
AUTO = ['down', 'attack', 'attack', 'down', 'up', 'up', 'left', 'left', 'left', 'left', 'down', 'down']

DIRS_D = {"up": (0, -1), "down": (0, 1), "left": (-1, 0), "right": (1, 0)}

def parse_dungeon():
    walls, monsters, treasures, start, exitc = set(), {}, set(), None, None
    for y, row in enumerate(PARAMS["map"]):
        for x, ch in enumerate(row):
            if ch == "#":
                walls.add((x, y))
            elif ch == "M":
                monsters[(x, y)] = PARAMS["monster_hp"]
            elif ch == "T":
                treasures.add((x, y))
            elif ch == "P":
                start = (x, y)
            elif ch == "E":
                exitc = (x, y)
    return walls, monsters, treasures, start, exitc

def dungeon_step(state, cmd):
    walls, monsters, treasures, player, hp, score = state
    if cmd == "attack":
        for (mx, my) in list(monsters):
            if abs(mx - player[0]) + abs(my - player[1]) == 1:
                monsters[(mx, my)] -= 25
                if monsters[(mx, my)] <= 0:
                    del monsters[(mx, my)]
                    score += 30
                else:
                    hp -= 10
                break
        return (walls, monsters, treasures, player, hp, score)
    dx, dy = DIRS_D.get(cmd, (0, 0))
    nxt = (player[0] + dx, player[1] + dy)
    if nxt not in walls and nxt not in monsters:
        player = nxt
    if player in treasures:
        treasures = treasures - {player}
        score += 50
    return (walls, monsters, treasures, player, hp, score)

def dungeon_result(state, exitc):
    walls, monsters, treasures, player, hp, score = state
    if player == exitc:
        return "WIN"
    if hp <= 0:
        return "DEFEATED"
    return "ONGOING"

def auto_play():
    walls, monsters, treasures, start, exitc = parse_dungeon()
    state = (walls, monsters, treasures, start, 100, 0)
    print("Dungeon tribute: auto session")
    for i, cmd in enumerate(AUTO):
        state = dungeon_step(state, cmd)
        walls, monsters, treasures, player, hp, score = state
        print("Step %d: %s pos %s hp %d monsters %d score %d" % (i + 1, cmd, player, hp, len(monsters), score))
        if dungeon_result(state, exitc) != "ONGOING":
            break
    print("FINAL SCORE: %d" % (state[5] + state[4]))
    print("RESULT: %s" % dungeon_result(state, exitc))

def play():
    walls, monsters, treasures, start, exitc = parse_dungeon()
    state = (walls, monsters, treasures, start, 100, 0)
    print("Dungeon tribute: type up/down/left/right/attack, or quit. Reach the exit, grab treasure, defeat monsters.")
    for line in sys.stdin:
        cmd = line.strip().lower()
        if cmd == "quit":
            break
        if cmd not in DIRS_D and cmd != "attack":
            print("Unknown command: %s" % cmd)
            continue
        state = dungeon_step(state, cmd)
        walls, monsters, treasures, player, hp, score = state
        print("pos %s hp %d monsters %d score %d" % (player, hp, len(monsters), score))
        if dungeon_result(state, exitc) != "ONGOING":
            break
    print("FINAL SCORE: %d" % (state[5] + state[4]))
    print("RESULT: %s" % dungeon_result(state, exitc))

if __name__ == "__main__":
    if "--play" in sys.argv:
        play()
    else:
        auto_play()

import sys
PARAMS = {'start_row': 2, 'spawns': [[0, 2], [7, 3], [14, 1]]}
AUTO = ['shoot', 'shoot', 'shoot', 'shoot', 'shoot', 'shoot', 'down', 'shoot', 'shoot', 'shoot', 'shoot', 'shoot', 'shoot', 'up', 'up', 'shoot', 'shoot', 'shoot', 'shoot', 'shoot', 'stay']

def auto_play():
    player = [2, PARAMS["start_row"]]
    enemies = []
    schedule = dict((t, r) for t, r in PARAMS["spawns"])
    score, lives = 0, 3
    print("Scrolling tribute: auto session")
    for tick, cmd in enumerate(AUTO):
        if tick in schedule:
            enemies.append([11, schedule[tick]])
        if cmd == "up":
            player[1] = max(0, player[1] - 1)
        elif cmd == "down":
            player[1] = min(5, player[1] + 1)
        elif cmd == "left":
            player[0] = max(0, player[0] - 1)
        elif cmd == "right":
            player[0] = min(11, player[0] + 1)
        elif cmd == "shoot":
            for e in list(enemies):
                if e[1] == player[1] and player[0] < e[0] <= player[0] + 4:
                    enemies.remove(e)
                    score += 100
                    break
        enemies = [[x - 1, y] for (x, y) in enemies]
        if any((x, y) == (player[0], player[1]) for (x, y) in enemies):
            lives -= 1
            enemies = [e for e in enemies if (e[0], e[1]) != (player[0], player[1])]
        score += 10
        print("Tick %d: %s player %s enemies %d score %d lives %d" % (tick + 1, cmd, tuple(player), len(enemies), score, lives))
        if lives <= 0:
            break
    print("FINAL SCORE: %d" % score)
    print("RESULT: %s" % ("SURVIVED" if lives > 0 else "OUT OF LIVES"))

def play():
    player = [2, PARAMS["start_row"]]
    enemies = []
    schedule = dict((t, r) for t, r in PARAMS["spawns"])
    score, lives, tick = 0, 3, 0
