import sys
PARAMS = {'pieces': ['bolt', 'gear', 'star', 'moon', 'bolt', 'gear', 'star', 'moon']}
AUTO = [['left', 'drop'], ['drop'], ['right', 'drop'], ['rotate', 'drop'], ['left', 'rotate', 'drop'], ['drop'], ['right', 'right', 'drop'], ['left', 'drop']]

def auto_play():
    heights = [0] * 6
    score, lines = 0, 0
    print("Puzzle tribute: auto session")
    for pi, piece in enumerate(PARAMS["pieces"]):
        cmds = AUTO[pi] if pi < len(AUTO) else ["drop"]
        col, vertical = 2, False
        for cmd in cmds:
            if cmd == "left":
                col = max(0, col - 1)
            elif cmd == "right":
                col = min(5, col + 1)
            elif cmd == "rotate":
                vertical = not vertical
            elif cmd == "drop":
                break
        if vertical:
            heights[col] += 2
        else:
            if col >= 5:
                col = 4
            heights[col] += 1
            heights[col + 1] += 1
        cleared = 0
        while min(heights) > 0:
            heights = [h - 1 for h in heights]
            cleared += 1
        lines += cleared
        score += cleared * 100 + 10
        print("Piece %d: %s col %d %s heights %s score %d" % (pi + 1, piece, col, "vertical" if vertical else "flat", heights, score))
    print("FINAL SCORE: %d" % score)
    print("RESULT: LINES %d" % lines)

def play():
    heights = [0] * 6
    score, lines = 0, 0
    print("Puzzle tribute: type left/right/rotate/drop per piece, or quit. Fill rows to clear them.")
    pi = 0
    col, vertical = 2, False
    for line in sys.stdin:
        cmd = line.strip().lower()
        if cmd == "quit":
            break
        if pi >= len(PARAMS["pieces"]):
            break
        if cmd == "left":
            col = max(0, col - 1)
        elif cmd == "right":
            col = min(5, col + 1)
        elif cmd == "rotate":
            vertical = not vertical
        elif cmd == "drop":
            piece = PARAMS["pieces"][pi]
            if vertical:
                heights[col] += 2
            else:
                if col >= 5:
                    col = 4
                heights[col] += 1
                heights[col + 1] += 1
            cleared = 0
            while min(heights) > 0:
                heights = [h - 1 for h in heights]
                cleared += 1
            lines += cleared
            score += cleared * 100 + 10
            print("Piece %d: %s heights %s score %d" % (pi + 1, piece, heights, score))
            pi += 1
            col, vertical = 2, False
        else:
            print("Unknown command: %s" % cmd)
    print("FINAL SCORE: %d" % score)
    print("RESULT: LINES %d" % lines)

if __name__ == "__main__":
    if "--play" in sys.argv:
        play()
    else:
        auto_play()
